package com.greenocean.backend.professional.service;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.identity.AccessPolicy;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;
import java.util.*;import java.time.*;
@Service @Transactional
public class ProfessionalAuthority {
 private final JdbcTemplate db;private final GrowthLibrary staff;private final AccessPolicy access;private final boolean enabled;
 public ProfessionalAuthority(JdbcTemplate db,GrowthLibrary staff,AccessPolicy access,@Value("${greenocean.clinic.enabled:false}")boolean enabled){this.db=db;this.staff=staff;this.access=access;this.enabled=enabled;}
 public record Scope(@jakarta.validation.constraints.Pattern(regexp="IR") @jakarta.validation.constraints.NotNull String country,@jakarta.validation.constraints.Pattern(regexp="TEXT|AUDIO|VIDEO") @jakarta.validation.constraints.NotNull String mode){}
 public record Decision(@jakarta.validation.constraints.Min(1) long revision,@jakarta.validation.constraints.NotBlank String state,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=2000)String reason,String category,String verifiedName,String issuer,String licenseIdentifier,String method,String source,String evidence,Instant validFrom,Instant validUntil,Instant recheckAt,@jakarta.validation.constraints.Size(max=3) List<@jakarta.validation.Valid Scope> scopes,@jakarta.validation.constraints.Size(max=20)List<@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=100)String> verifiedSpecialties){
 public Decision(long revision,String state,String reason,String category,String verifiedName,String issuer,String licenseIdentifier,String method,String source,String evidence,Instant validFrom,Instant validUntil,Instant recheckAt,List<Scope> scopes){this(revision,state,reason,category,verifiedName,issuer,licenseIdentifier,method,source,evidence,validFrom,validUntil,recheckAt,scopes,List.of());}
 }
 public record Release(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Pattern(regexp="IR") String country,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Pattern(regexp="TEXT|AUDIO|VIDEO") String mode,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Pattern(regexp="PLATFORM|PROFESSIONAL_SCOPE|PATIENT_IDENTITY|DATA_PROCESSING|TERMS|OPERATIONS|MEDIA_PROVIDER|PAYMENT_PROVIDER|SETTLEMENT|PROMOTION") String purpose,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(min=10,max=2000) String evidence,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Future Instant expiresAt){}
 public void actor(UUID who){db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",who);access.require(who,"COMMUNITY");}
 public void lock(UUID who){db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","professional-schedule:"+who);}
 public void owner(UUID who){actor(who);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_profiles WHERE user_id=?)",Boolean.class,who)))throw new NotFoundException("Professional workspace was not found");}
 public void offer(UUID who,String country,String mode){actor(who);if(!enabled||!Boolean.TRUE.equals(db.queryForObject("SELECT professional_scope_live(?,?::char(2),?) AND EXISTS(SELECT 1 FROM account_eligibility WHERE user_id=? AND residence_country=? AND(current_country IS NULL OR current_country=?))",Boolean.class,who,country,mode,who,country,country)))throw new ForbiddenException("Current profession, jurisdiction, modality and independent clinic release approvals are required");access.require(who,"PROFESSIONAL_CARE");}
 public void application(UUID id,UUID who,String category,String license){actor(who);if(!Set.of("PSYCHOLOGIST","COUNSELOR","PSYCHIATRIST").contains(category))throw new IllegalArgumentException("Select psychologist, counselor or psychiatrist");db.update("UPDATE professional_verifications SET professional_category=?,license_identifier=? WHERE id=? AND professional_user_id=?",category,license,id,who);}
 public List<Map<String,Object>> sources(UUID actor){staff.staff(actor);return db.queryForList("SELECT category,origin,method,automation_enabled FROM professional_verification_sources ORDER BY category,origin");}
 public List<Map<String,Object>> queue(UUID actor,int page){staff.staff(actor);if(page<0||page>10000)throw new IllegalArgumentException("Invalid review page");return db.queryForList("SELECT v.id,v.professional_user_id,v.professional_category,v.qualification_state,v.qualification_revision,v.submitted_at FROM professional_verifications v WHERE v.qualification_state IN('SUBMITTED','DOCUMENTS_PENDING','UNDER_VERIFICATION','NEEDS_CORRECTION') ORDER BY v.submitted_at,v.id LIMIT 20 OFFSET ?",page*20);}
 public Map<String,Object> workspace(UUID who){owner(who);return (Map<String,Object>)jsonSafe(Map.of("authorizedModes",enabled?db.queryForList("SELECT mode FROM unnest(ARRAY['TEXT','AUDIO','VIDEO']) AS allowed(mode) WHERE professional_scope_live(?,'IR',mode) ORDER BY mode",String.class,who):List.of(),"qualifications",db.queryForList("SELECT id,professional_category,CASE WHEN qualification_state='VERIFIED' AND(valid_until<=CURRENT_TIMESTAMP OR recheck_at<=CURRENT_TIMESTAMP) THEN 'EXPIRED' ELSE qualification_state END AS qualification_state,qualification_revision,verified_name,license_issuer,valid_from,valid_until,recheck_at,reviewed_at FROM professional_verifications WHERE professional_user_id=? ORDER BY submitted_at DESC LIMIT 20",who),"currentlyQualified",db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,who),"clinicEnabled",enabled,"profile",db.queryForMap("SELECT profile_revision,title,bio,languages,consultation_modes,accepting_new_clients,service_description,conditions_of_service FROM professional_profiles WHERE user_id=?",who),"slots",db.queryForList("SELECT id,starts_at,ends_at,consultation_mode,status,price_units,currency,timezone,revision FROM professional_availability_slots WHERE professional_user_id=? ORDER BY starts_at DESC LIMIT 100",who),"rules",db.queryForList("SELECT * FROM professional_calendar_rules WHERE professional_id=? ORDER BY valid_from,id LIMIT 50",who),"exceptions",db.queryForList("SELECT id,starts_at,ends_at,reason,active FROM professional_calendar_exceptions WHERE professional_id=? ORDER BY starts_at DESC LIMIT 100",who)));}
 public static Object jsonSafe(Object value){if(value instanceof java.sql.Array array)try{return jsonSafe(array.getArray());}catch(java.sql.SQLException ex){throw new IllegalStateException("Unable to read private metadata",ex);}if(value instanceof Object[] array)return java.util.Arrays.stream(array).map(ProfessionalAuthority::jsonSafe).toList();if(value instanceof Map<?,?> map){Map<String,Object> result=new LinkedHashMap<>();map.forEach((key,item)->result.put(key.toString(),jsonSafe(item)));return result;}if(value instanceof List<?> list)return list.stream().map(ProfessionalAuthority::jsonSafe).toList();return value;}
 public void decide(UUID actor,UUID id,Decision in){staff.staff(actor);var owners=db.queryForList("SELECT professional_user_id FROM professional_verifications WHERE id=?",id);if(owners.isEmpty())throw new NotFoundException("Application was not found");UUID who=(UUID)owners.getFirst().get("professional_user_id");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",who);lock(who);var rows=db.queryForList("SELECT * FROM professional_verifications WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new NotFoundException("Application was not found");var v=rows.getFirst();if(actor.equals(who))throw new ForbiddenException("Independent credential verification is required");if(((Number)v.get("qualification_revision")).longValue()!=in.revision())throw new ConflictException("Application changed; review the current revision");String state=in.state();if(!Set.of("UNDER_VERIFICATION","NEEDS_CORRECTION","VERIFIED","REJECTED","SUSPENDED","REVOKED","EXPIRED").contains(state))throw new IllegalArgumentException("Unsupported qualification transition");text(in.reason(),2000);
 if(state.equals("VERIFIED")){actor(who);if(!Set.of("PSYCHOLOGIST","COUNSELOR","PSYCHIATRIST").contains(Objects.toString(in.category(),"")))throw new IllegalArgumentException("Unsupported profession");text(in.verifiedName(),200);text(in.issuer(),300);text(in.licenseIdentifier(),100);text(in.method(),80);text(in.source(),1000);text(in.evidence(),2000);if(in.evidence().trim().length()<10||in.source().trim().length()<10)throw new IllegalArgumentException("Specific independent verification evidence and source required");if(!Set.of("OFFICIAL_REGISTER_HUMAN","AUTHORIZED_REGISTRY_ADAPTER").contains(in.method()))throw new IllegalArgumentException("Independent official-source verification required");if(!in.method().equals("OFFICIAL_REGISTER_HUMAN"))throw new ConflictException("No authorized registry adapter is configured");if(in.validFrom()==null||in.validUntil()==null||in.recheckAt()==null||in.validFrom().isAfter(Instant.now())||!in.validUntil().isAfter(Instant.now())||!in.recheckAt().isAfter(Instant.now())||in.recheckAt().isAfter(in.validUntil()))throw new IllegalArgumentException("Current validity and recheck dates are required");java.net.URI sourceUri;try{sourceUri=java.net.URI.create(in.source());}catch(IllegalArgumentException bad){throw new IllegalArgumentException("Use an official verification source URI");}String origin="https://"+Objects.toString(sourceUri.getHost(),"").toLowerCase(java.util.Locale.ROOT);if(!"https".equals(sourceUri.getScheme())||sourceUri.getUserInfo()!=null||sourceUri.getFragment()!=null||(sourceUri.getPort()!=-1&&sourceUri.getPort()!=443)||!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_verification_sources WHERE category=? AND origin=? AND method='HUMAN_ONLY' AND NOT automation_enabled)",Boolean.class,in.category(),origin)))throw new IllegalArgumentException("Use the approved profession-specific official human register; no automated registry success is claimed");if(!in.category().equals(v.get("professional_category"))||!in.licenseIdentifier().equals(v.get("license_identifier")))throw new ConflictException("Credential identity changed; request correction");if(in.scopes()==null||in.scopes().isEmpty()||in.scopes().size()>3||in.scopes().stream().anyMatch(s->!"IR".equals(s.country())||!Set.of("TEXT","AUDIO","VIDEO").contains(s.mode())))throw new IllegalArgumentException("Explicit Iran consultation modes are required; prescribing is disabled");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_application_documents WHERE application_id=?) AND NOT EXISTS(SELECT 1 FROM professional_application_documents WHERE application_id=? AND (scan_status<>'CLEAN' OR encryption_version<>1 OR scanner_reference IS NULL))",Boolean.class,id,id)))throw new ConflictException("Every credential document needs encrypted storage and a genuine clean scanner result");
 db.update("UPDATE professional_verifications SET professional_category=?,verified_name=?,license_issuer=?,license_identifier=?,verification_method=?,verification_source=?,evidence_reference=?,valid_from=?,valid_until=?,recheck_at=?,status='APPROVED',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?",in.category(),in.verifiedName(),in.issuer(),in.licenseIdentifier(),in.method(),in.source(),in.evidence(),time(in.validFrom()),time(in.validUntil()),time(in.recheckAt()),actor,id);
 var specialties=in.verifiedSpecialties()==null?List.<String>of():in.verifiedSpecialties();if(specialties.size()>20||specialties.stream().anyMatch(vv->vv==null||vv.isBlank()||vv.length()>100))throw new IllegalArgumentException("Bounded independently verified specialties required");db.update("UPDATE professional_verifications SET verified_specialties=? WHERE id=?",specialties.toArray(String[]::new),id);db.update("DELETE FROM professional_scope_authorizations WHERE application_id=?",id);for(var scope:in.scopes())db.update("INSERT INTO professional_scope_authorizations(application_id,country_code,mode) VALUES(?,?,?) ON CONFLICT DO NOTHING",id,scope.country(),scope.mode());db.update("UPDATE professional_profiles SET verification_status='VERIFIED',verified_at=CURRENT_TIMESTAMP WHERE user_id=?",who);db.update("INSERT INTO professional_care_regions(professional_user_id,country_code,approved_by,expires_at) VALUES(?,'IR',?,?) ON CONFLICT(professional_user_id,country_code) DO UPDATE SET approved_by=EXCLUDED.approved_by,approved_at=CURRENT_TIMESTAMP,expires_at=EXCLUDED.expires_at",who,actor,time(in.recheckAt()));
 }else if(Set.of("REJECTED","SUSPENDED","REVOKED","EXPIRED").contains(state)){db.update("UPDATE professional_profiles SET verification_status='SUSPENDED',verified_at=NULL,accepting_new_clients=FALSE WHERE user_id=?",who);db.update("UPDATE professional_verifications SET status='REJECTED',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?",actor,id);db.update("UPDATE professional_availability_slots SET status='CANCELLED' WHERE professional_user_id=? AND status IN('DRAFT','AVAILABLE')",who);db.update("DELETE FROM professional_appointment_readiness WHERE actor_id=?",who);}
 db.update("UPDATE professional_verifications SET qualification_state=?,qualification_revision=qualification_revision+1 WHERE id=?",state,id);db.update("INSERT INTO professional_qualification_decisions(application_id,revision,actor_id,state,reason,evidence_reference,evidence_snapshot) SELECT ?,?,?,?,?,?,to_jsonb(v)-'document_names'-'notes' FROM professional_verifications v WHERE v.id=?",id,in.revision(),actor,state,in.reason(),in.evidence(),id);audit(actor,"PROFESSIONAL_QUALIFICATION_"+state,id,in.reason());}
 public record Profile(@jakarta.validation.constraints.Min(1)long revision,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=100)String title,@jakarta.validation.constraints.Size(max=4000)String bio,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Size(max=20)List<@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=80)String> languages,@jakarta.validation.constraints.Size(max=2000)String serviceDescription,@jakarta.validation.constraints.Size(max=2000)String conditionsOfService,boolean acceptingNewClients){}
 public void profile(UUID who,Profile in){owner(who);lock(who);if(in.title()==null||in.title().isBlank()||in.languages()==null||in.languages().size()>20)throw new IllegalArgumentException("Bounded profile details required");if(db.update("UPDATE professional_profiles SET title=?,bio=?,languages=?,service_description=?,conditions_of_service=?,accepting_new_clients=?,profile_revision=profile_revision+1 WHERE user_id=? AND profile_revision=?",in.title(),Objects.toString(in.bio(),""),in.languages().toArray(String[]::new),Objects.toString(in.serviceDescription(),""),Objects.toString(in.conditionsOfService(),""),in.acceptingNewClients(),who,in.revision())!=1)throw new ConflictException("Profile changed on another device; your current input was not saved");db.update("INSERT INTO professional_profile_history(professional_id,revision,title,bio,languages,service_description,conditions_of_service) SELECT user_id,profile_revision,title,bio,languages,service_description,conditions_of_service FROM professional_profiles WHERE user_id=?",who);audit(who,"PROFESSIONAL_PROFILE_UPDATED",who,"Self-declared profile metadata; no credential or scope authorization changed");}
 public void release(UUID actor,Release in){staff.admin(actor);if(in.purpose()==null||!Set.of("PLATFORM","PROFESSIONAL_SCOPE","PATIENT_IDENTITY","DATA_PROCESSING","TERMS","OPERATIONS","MEDIA_PROVIDER","PAYMENT_PROVIDER","SETTLEMENT","PROMOTION").contains(in.purpose()))throw new IllegalArgumentException("Select a specific release approval purpose");if(!"IR".equals(in.country())||!Set.of("TEXT","AUDIO","VIDEO").contains(in.mode())||in.expiresAt()==null||!in.expiresAt().isAfter(Instant.now()))throw new IllegalArgumentException("Explicit future Iran/mode approval required");text(in.evidence(),2000);db.update("INSERT INTO clinic_release_approvals(country_code,mode,purpose,evidence_reference,approved_by,expires_at) VALUES(?,?,?,?,?,?)",in.country(),in.mode(),in.purpose(),in.evidence(),actor,time(in.expiresAt()));audit(actor,"CLINIC_RELEASE_EVIDENCE",null,in.evidence());}
 public void audit(UUID actor,String action,UUID id,String reason){db.update("INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,metadata) VALUES(?,?,'PROFESSIONAL_CARE',?,jsonb_build_object('reason',?::text))",actor,action,id,reason);}
 public static java.time.OffsetDateTime time(Instant t){return t==null?null:t.truncatedTo(java.time.temporal.ChronoUnit.MICROS).atOffset(ZoneOffset.UTC);}
 public static String text(String value,int max){if(value==null||value.trim().length()<3||value.length()>max)throw new IllegalArgumentException("Provide bounded, specific evidence or wording");return value.trim();}
}
